value.query:
{
  residentialPlans(zipCode: "77002", monthlyUsage: 1000) {
    title
    price
    term
    rateType
    supplier { name }
    rates { usageKwh allInRateUsdPerKwh avgMonthlyBillUsd }
    supplierScores { energyBotRating plansAndRates customerService renewablePlans pucRating }
    headlessEnrollmentUrl
  }
}

{
  businessPlans(zipCode: "75070", annualUsageInkWh: 23000, isMoveIn: true) {
    id
    term
    price
    monthlyFee
    supplier { name }
    enrollmentUrl
    agreementUrl
  }
}

{
  energyInfoByState(stateCode: "TX", isBusiness: false) {
    averagePrice
    stateName
    electricityGenerationPercentage {
      renewableGeneration
      nonRenewableGeneration
    }
  }
}
